def _resolve(self, name: str):
    try:
        value = super().__getitem__(name)
    except KeyError:
        raise KeyError(name) from None
    if value is None:
        value = self._builders[name]()
        super().__setitem__(name, value)
    return value

    def get(self, name: str, default=None):
        try:
            return self._resolve(name)
        except KeyError:
            return default


