def radial_wf(n, l, r):
    if l >= n or l < 0:
        return np.zeros_like(r)
    norm = np.sqrt((2.0/n)**3 * factorial(n-l-1) / (2*n*factorial(n+l)))
    rho = 2.0 * r / n
    lag = genlaguerre(n-l-1, 2*l+1)(rho)
    return norm * np.power(rho, l) * lag * np.exp(-rho/2)

