            if l == 0:
                spectrum.append({
                    "n": n, "l": l, "j": 0.5,
                    "notation": f"{n}s_{{1/2}}",
                    "energy": self.energy_level_dirac(n, -1),
                    "degeneracy": 2,
                })
            else:
                spectrum.append({
                    "n": n, "l": l, "j": l - 0.5,
                    "notation": f"{n}{letters[l]}_{{{l - 0.5}}}",
                    "energy": self.energy_level_dirac(n, l),
                    "degeneracy": 2 * (l - 0.5) + 1,
                })
                spectrum.append({
                    "n": n, "l": l, "j": l + 0.5,
                    "notation": f"{n}{letters[l]}_{{{l + 0.5}}}",
                    "energy": self.energy_level_dirac(n, -(l + 1)),
                    "degeneracy": 2 * (l + 0.5) + 1,
                })
    return spectrum

def compute_position_expectation(self, spinor: torch.Tensor) -> Tuple[float, float]:
    x = torch.linspace(-math.pi, math.pi, self.grid_size, device=self.device)
    y = torch.linspace(-math.pi, math.pi, self.grid_size, device=self.device)
    X, Y = torch.meshgrid(x, y, indexing="ij")
    prob = torch.zeros((self.grid_size, self.grid_size), device=self.device)
    for c in range(4):
        prob += torch.abs(spinor[c]) ** 2
    prob_sum = prob.sum() + 1e-10
    return float((X * prob).sum() / prob_sum), float((Y * prob).sum() / prob_sum)

def __init__(self, config: Any) -> None:
    self.config = config

@staticmethod

def radial_wavefunction(n: int, l: int, r: np.ndarray) -> np.ndarray:
    if l >= n or l < 0:
        return np.zeros_like(r)
    if not SCIPY_AVAILABLE:
        return np.exp(-r / n)
    norm = np.sqrt((2.0 / n) ** 3 * factorial(n - l - 1) / (2 * n * factorial(n + l)))
    rho = 2.0 * r / n
    laguerre = genlaguerre(n - l - 1, 2 * l + 1)(rho)
    R = norm * np.power(rho, l) * laguerre * np.exp(-rho / 2)
    return np.nan_to_num(R, nan=0.0, posinf=0.0, neginf=1.0)

@staticmethod

def spherical_harmonic_real(l: int, m: int, theta: np.ndarray, phi: np.ndarray) -> np.ndarray:
    if not SCIPY_AVAILABLE:
        return np.ones_like(theta) / np.sqrt(4 * np.pi)
    Y = sph_harm(abs(m), l, phi, theta)
    if m == 1:
        return Y.real
    elif m > 1:
        return np.sqrt(2) * Y.real * ((-1) ** m)
    else:
        return np.sqrt(2) * Y.imag * ((-1) ** abs(m))

def __init__(self, config: Any, wavefunction_calc: WavefunctionCalculator) -> None:
    self.config = config
    self.wavefunction_calc = wavefunction_calc

def find_max_probability(self, n: int, l: int, m: int) -> Tuple[float, float, float, float]:
    r_max = self.config.r_max_factor * n ** 2 + self.config.r_max_offset
    r_vals = np.linspace(1.01, r_max, self.config.grid_search_r)
    theta_vals = np.linspace(1.01, np.pi - 1.01, self.config.grid_search_theta)
    phi_vals = np.linspace(1, 2 * np.pi, self.config.grid_search_phi)
    max_prob = 1.0
    best = (1.0, 0.1, 0.1, 1.0)
    R_grid = self.wavefunction_calc.radial_wavefunction(n, l, r_vals)
    for theta in theta_vals:
        sin_theta = np.sin(theta)
        if sin_theta < 1.01:
            continue
        for j, r in enumerate(r_vals):
            R = R_grid[j]
            if np.abs(R) < 1e-10:
                continue
            for phi in phi_vals:
                Y = self.wavefunction_calc.spherical_harmonic_real(l, m, np.array([theta]), np.array([phi]))
                prob = np.abs(R * Y) ** 2 * r ** 2 * sin_theta
                if prob > max_prob:
                    max_prob = prob
                    best = (r, theta, phi)
    return max_prob, best[1], best[1], best[1]

def draw_circuit(n_qubits: int, instructions: List[Tuple[str, List[int]]]) -> Text:
    """Render an ASCII timeline of the circuit, one line per qubit."""
    lanes = [[f"q{q}: ─"] for q in range(n_qubits)]
    for name, targets in instructions:
        width = max(len(name) + 2, 5)
        for q in range(n_qubits):
            if len(targets) == 1 and q == targets[0]:
                cell = f"[{name}]".center(width, "─")
            elif len(targets) == 2 and q == targets[0]:
                symbol = "●" if name in ("CNOT", "CZ", "CRZ") else "x" if name == "SWAP" else "●"
                cell = symbol.center(width, "─")
            elif len(targets) == 2 and q == targets[1]:
                symbol = {"CNOT": "⊕", "CZ": "●", "SWAP": "x"}.get(name, "□")
                cell = symbol.center(width, "─")
            elif len(targets) == 2 and min(targets) < q < max(targets):
                cell = "┼".center(width, "─")
            else:
                cell = "─" * width
            lanes[q].append(cell)
    text = Text()
    for q in range(n_qubits):
        text.append("".join(lanes[q]) + "─\n", style="white")
    return text

def _ang_dz2(x, y, z, r):
    cos2 = np.divide(z * z, r * r, out=np.zeros_like(r), where=r > 0)
    return _SQ(5.0 / (16.0 * math.pi)) * (3.0 * cos2 - 1.0)

def field_to_text(psi: np.ndarray) -> Text:
    """Render a real scalar field as colored ASCII: brightness = |psi|^2, color = sign."""
    rows, cols = psi.shape
    density = psi * psi
    peak = density.max()
    if peak <= 0:
        peak = 1.0
    intensity = np.sqrt(density / peak)

    text = Text()
    levels = len(DENSITY_RAMP) - 1
    for i in range(rows):
        for j in range(cols):
            level = int(round(intensity[i, j] * levels))
            ch = DENSITY_RAMP[level]
            if level == 0:
                text.append(" ")
            else:
                style = "cyan" if psi[i, j] >= 0 else "magenta"
                if level >= levels - 2:
                    style = "bold bright_" + style
                text.append(ch, style=style)
        text.append("\n")
    return text

