def ghz_state(self, n_qubits: int = 3, backend: str = "schrodinger") -> QuantumResult:
    circ = self.create_circuit(n_qubits)
    circ.h(0)
    for i in range(n_qubits - 1):
        circ.cnot(i, i + 1)
    return self.run_circuit(circ, backend=backend)

